import { motion } from "framer-motion";

const teamMembers = [
  {
    name: "Dr Nesrine Sakhri",
    role: "Fondatrice et Médecin Chef",
    image: require("../../../Images/team/membre1.jpg"),
  },
  {
    name: "Sakhri Wail",
    role: "Créateur du site web",
    image: require("../../../Images/team/wail.jpg"),
  },
  {
    name: "Omar I.b",
    role: "Comptable",
    image: require("../../../Images/team/comptable1.jpg"),
  },
  {
    name: "Ellye S.",
    role: "Sous-médecin chef",
    image: require("../../../Images/team/membre2.jpg"),
  },
  {
    name: "Rachid A.",
    role: "Infirmier en Chef",
    image: require("../../../Images/team/infirmier.jpg"),
  },
  {
    name: "Oussama S.",
    role: "Chef Du block opératoir",
    image: require("../../../Images/team/doc5.jpg"),
  },
  {
    name: "Skander B.",
    role: "Responsable en Chef de nuit",
    image: require("../../../Images/team/doc6.jpg"),
  },
];

const TeamSection = () => {
  return (
    <section className="container mt-5 text-center">
      <motion.h2 
        className="text-primary fw-bold mb-4"
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8 }}
      >
        Notre Équipe
      </motion.h2>
      <div className="row justify-content-center">
        {teamMembers.map((member, index) => (
          <motion.div
            key={index}
            className="col-lg-3 col-md-6 col-sm-12 mb-4"
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, delay: index * 0.3 }}
          >
            <img
              src={member.image}
              alt={member.name}
              className="img-fluid rounded-circle shadow"
              style={{ width: "150px", height: "150px" }}
            />
            <h4 className="mt-2">{member.name}</h4>
            <p className="text-muted">{member.role}</p>
          </motion.div>
        ))}
      </div>
    </section>
  );
};

export default TeamSection;
