import React from "react";
import ServiceCard from '../modal/ServiceCard';
import Button from 'react-bootstrap/Button';
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faMagnifyingGlass } from '@fortawesome/free-solid-svg-icons';

const services = [
  {
    title: 'MRI Scans',
    description: 'We provide high-quality MRI scans for accurate diagnoses and medical evaluations.',
    imgSrc: 'mri.png',
    imgSrcs: 'mri.jpg',
    secretary: '+213 555 123 456',
    doctor: 'Dr. Ahmed Benyahia',
    workHours: '08:00 - 16:00',
  },
  {
    title: 'Gastroenterology',
    description: 'Our gastroenterology services include diagnosis and treatment of digestive disorders.',
    imgSrc: 'gastroenterology.png',
    imgSrcs: 'gastroenterology1.webp',
    secretary: '+213 555 987 654',
    doctor: 'Dr. Zyed Amari',
    workHours: '09:00 - 17:00',
  },
  {
    title: 'Surgery',
    description: 'Our surgical team specializes in various procedures to ensure optimal patient care.',
    imgSrc: 'surgery.png',
    imgSrcs: 'surgery.jpg',
    secretary: '+213 555 222 333',
    doctor: 'Dr. Sakhri Nesrine',
    workHours: '10:00 - 18:00',
  },
  {
    title: 'Health Insurance',
    description: 'We offer comprehensive health insurance plans to cover medical expenses effectively.',
    imgSrc: 'shield.png',
    imgSrcs: 'Health Insurance.jpg',
    secretary: '+213 555 444 555',
    doctor: 'Dr. lathani Lounis',
    workHours: '07:30 - 15:30',
  },
  {
    title: 'General Health',
    description: 'Get professional consultations and treatments for a wide range of health concerns.',
    imgSrc: 'healthy.png',
    imgSrcs: 'General-Health.webp',
    secretary: '+213 555 666 777',
    doctor: 'Dr. Ellyne ',
    workHours: '08:30 - 16:30',
  },
];

function Avaibleservices() {
  return (
    <div className="Whyuscontainer">
      <div className="titlecardplace">
        <h2>Why choose us?</h2>
      </div>
      <div className="cardplacement">
        {services.map((service, index) => (
          <ServiceCard 
            key={index} 
            title={service.title} 
            description={service.description} 
            imgSrc={service.imgSrc} 
            imgSrcs={service.imgSrcs} 
            secretary={service.secretary} 
            doctor={service.doctor} 
            workHours={service.workHours} 
          />
        ))}

      </div>
      {/* Bouton "See More" */}
      <div className="buttonCardPlace">
        <Button className="btn btn-primary" style={{ borderRadius: '8px', width: '160px', height:'45px'}}>
          <a href="#Services" style={{ color: 'white', textDecoration: 'none', fontSize:'18px' }}>
            See More <FontAwesomeIcon icon={faMagnifyingGlass} />
          </a>
        </Button>
      </div>
    </div>
  );
}

export default Avaibleservices;
