import { useEffect, useState, useCallback } from "react";
import "./Navstyle.css";
import { NavLink } from "react-router-dom";
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faEnvelope, faLocationPin, faPhone } from '@fortawesome/free-solid-svg-icons';

const Header = () => {
  const [isScrollingDown, setIsScrollingDown] = useState(false);

  // Utilisation de useCallback pour éviter la recréation de la fonction handleScroll
  const handleScroll = useCallback(() => {
    let currentScrollY = window.scrollY;
    setIsScrollingDown(prevScrollY => currentScrollY > prevScrollY);
  }, []);

  useEffect(() => {
    window.addEventListener("scroll", handleScroll);

    // Animation des items du menu
    const items = ["#li1", "#li2", "#li3", "#li4"];
    items.forEach((item, index) => {
      const element = document.querySelector(item);
      if (element) {
        setTimeout(() => {
          element.style.visibility = "visible";
          element.style.opacity = "1";
        }, 550 + index * 100); // Timer échelonné pour chaque item
      }
    });

    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, [handleScroll]);

  return (
    <header className={`navbar-container ${isScrollingDown ? "hidden" : ""}`}>
      {/* Informations de contact */}
      <div className="header-info-container d-none d-md-flex">
        <p><FontAwesomeIcon icon={faPhone} /> +213 0775 51 74 55</p>
        <p><FontAwesomeIcon icon={faEnvelope} /> info@mywebsite.com</p>
        <p><FontAwesomeIcon icon={faLocationPin} /> 3 street Amir Abd El Kader</p>
      </div>

      {/* Navbar Bootstrap */}
      <nav className="navbar navbar-expand-lg navbar-dark bg-dark">
        <div className="container-fluid">
        <NavLink className="nav-link" to="/MedVie">Vita Med</NavLink>

          <button 
            className="navbar-toggler" 
            type="button" 
            data-bs-toggle="collapse" 
            data-bs-target="#navbarSupportedContent" 
            aria-controls="navbarSupportedContent" 
            aria-expanded="false" 
            aria-label="Toggle navigation"
          >
            <span className="navbar-toggler-icon"></span>
          </button>

          <div className="collapse navbar-collapse" id="navbarSupportedContent">
            <ul className="navbar-nav mx-auto">
              <li className="nav-item" id="li1">
                <NavLink className="nav-link" to="/MedVie">Home</NavLink>
              </li>
              <li className="nav-item" id="li2">
                <NavLink className="nav-link" to="/Services">Service</NavLink>
              </li>
              <li className="nav-item" id="li3">
                <NavLink className="nav-link" to="/About">About</NavLink>
              </li>
              <li className="nav-item" id="li4">
                <NavLink className="nav-link" to="/contact">Contact</NavLink>
              </li>
            </ul>

            {/* Barre de recherche */}
            <form className="d-flex">
              <input className="form-control me-2" type="search" placeholder="Search" aria-label="Search" />
              <button className="btn btn-outline-success" type="submit" id="btn">Search</button>
            </form>
          </div>
        </div>
      </nav>
    </header>
  );
};

export default Header;
